int get_jpeg_dimensions(unsigned char* data, unsigned int data_size, int* width, int* height) {
    if (data_size < 2) {
        return -1;
    }

    // Check for JPEG Start of Image (SOI) marker
    if (data[0] != 0xFF || data[1] != 0xD8) {
        return -1;
    }

    int i = 2;
    while (i < data_size - 1) {
        // Find a JPEG marker
        if (data[i] == 0xFF) {
            unsigned char marker = data[i++];
            if (marker == 0xFF) {
                // Skip consecutive 0xFF bytes
                continue;
            }

            // Check for Start of Frame (SOF) marker
            if (marker == 0xC0 || marker == 0xC1 || marker == 0xC2 || marker == 0xC3 ||
                marker == 0xC5 || marker == 0xC6 || marker == 0xC7 || marker == 0xC9 ||
                marker == 0xCA || marker == 0xCB || marker == 0xCD || marker == 0xCE ||
                marker == 0xCF) {
                if (i + 3 >= data_size) {
                    return -1;
                }

                // Skip the length field
                unsigned int length = (data[i] << 8) | data[i + 1];
                i += 2;

                if (i + length >= data_size) {
                    return -1;
                }

                // Extract width and height
                *width = (data[i + 2] << 8) | data[i + 3];
                *height = (data[i + 3] << 8) | data[i + 4];
                return 0;
            }

            // Skip over the marker data
            if (i + 1 >= data_size) {
                return -1;
            }

            unsigned int length = (data[i] << 8) | data[i + 1];
            i += length + 2;
        } else {
            i++;
        }
    }

    return -1;
}

int get_jpeg_dimensions(unsigned char* data, unsigned int data_size, int* width, int* height) {
    // Check for Start of Image (SOI) marker (0xFFD8)
    if (data_size < 2 || data[0] != 0xFF || data[1] != 0xD8) {
        return -1;
    }

    unsigned int i = 2;

    // Skip any markers until we find a Start of Frame (SOF) marker
    while (i < data_size) {
        // Check for a marker (0xFF followed by non-0xFF byte)
        if (data[i] == 0xFF && i + 1 < data_size && data[i + 1] != 0xFF && data[i + 1] != 0x00) {
            unsigned char marker = data[i + 1];

            // Check if it's a Start of Frame (SOF) marker (0xFFC0-0xFFCF)
            if (marker >= 0xC0 && marker <= 0xCF) {
                // Check if there are enough bytes to read the header
                if (i + 7 >= data_size) {
                    return -1;
                }

                // Skip the marker and length (2 bytes)
                i += 2;

                // Read the height (2 bytes, little-endian)
                *height = (data[i + 1] << 8) | data[i];

                // Read the width (2 bytes, little-endian)
                *width = (data[i + 3] << 8) | data[i + 2];

                return 0;
            }

            // Skip the marker and the length of the segment
            if (i + 1 < data_size) {
                unsigned int segment_length = (data[i + 2] << 8) | data[i + 1];
                i += 2 + segment_length;
            } else {
                return -1;
            }
        } else {
            i++;
        }
    }

    // Could not find SOF marker
    return -1;
}
